using namespace std;
#define int long long
const int mod = 1e13+7;
const int INF = 1e9;
int32_t main() {
	// your code goes here
	int T;
	cin >> T;
	while(T--){
	int n;
	cin >> n;
	vector<int>a(n);
	for(auto &x:a) cin >> x;
	int ans1=-1;
	if(n==2) cout << abs(a[0]-a[1]) << '\n';
	else {
	for(int i=0;i<n-2;i++){
	    ans1=max(ans1,abs(a[i]-a[i+1]));
	}
	int ans2=-1;
	for(int i=1;i<n-1;i++){
	    ans2=max(ans2,abs(a[i]-a[i+1]));
	}
	
	cout << min(ans1,ans2) << '\n';
	}
	}
   return 0;
	
}
